import {callTool, listTools} from "./server.mjs";
(async () => {
  // unknown tool
  try { await callTool("foo", {}); console.log("FAIL: unknown tool accepted"); }
  catch(e){ console.log("ok unknown tool rejected:", e.message); }

  // missing title
  try { await callTool("ticket_create", {description:"x"}); console.log("FAIL missing title accepted"); }
  catch(e){ console.log("ok missing title rejected:", e.message); }

  // empty title
  try { await callTool("ticket_create", {title:"  ", description:"x"}); console.log("FAIL empty title accepted"); }
  catch(e){ console.log("ok empty title rejected:", e.message); }

  // extra field
  try { await callTool("ticket_create", {title:"a", description:"b", extra:1}); console.log("FAIL extra field accepted"); }
  catch(e){ console.log("ok extra field rejected:", e.message); }

  // bad priority
  try { await callTool("ticket_create", {title:"a", description:"b", priority:"urgent"}); console.log("FAIL bad priority accepted"); }
  catch(e){ console.log("ok bad priority rejected:", e.message); }

  // sequential ids + default priority
  const r1 = await callTool("ticket_create", {title:"A", description:"aa"});
  const r2 = await callTool("ticket_create", {title:"B", description:"bb", priority:"high"});
  const r3 = await callTool("ticket_create", {title:"C", description:"cc", priority:"low"});
  console.log("r1:", r1.content[0].text);
  console.log("r2:", r2.content[0].text);
  console.log("r3:", r3.content[0].text);

  // listTools schema
  const tools = await listTools();
  console.log("schema additionalProperties:", tools[0].inputSchema.additionalProperties);
  console.log("required:", JSON.stringify(tools[0].inputSchema.required));
})();
'"}

